    23→} from "lucide-react";
    24→import { createContext, useContext, useEffect, useState } from "react";
    25→import { toast } from "sonner";
    26→
    27→import { Button } from "@/components/ui/button";
    28→import { Card, CardContent } from "@/components/ui/card";
    29→import { Sheet, SheetContent } from "@/components/ui/sheet";
    30→import { useMediaQuery } from "@/hooks/use-media-query";
    31→import { cn } from "@/lib/utils";
    32→import { orpc } from "@/utils/orpc";
    33→import { BuilderCanvas } from "./builder-canvas";
    34→import { BuilderHeader } from "./builder-header";
    35→import { PropertiesPanel } from "./properties-panel";
    36→import { QuestionPalette } from "./question-palette";
    37→
    38→// Question type configs for drag overlay
    39→const questionTypeIcons: Record<string, React.ElementType> = {
    40→	text: ClipboardList,
    41→	textarea: ClipboardList,
    42→	multiple_choice: ClipboardList,
    43→	checkbox: ClipboardList,
    44→	dropdown: ClipboardList,
    45→	rating: ClipboardList,
    46→	nps: ClipboardList,
    47→	linear_scale: ClipboardList,
    48→	date: ClipboardList,
    49→	email: ClipboardList,
    50→	phone: ClipboardList,
    51→	file_upload: ClipboardList,
    52→};
    53→
    54→const questionTypeLabels: Record<string, string> = {
    55→	text: "Short Text",
    56→	textarea: "Long Text",
    57→	multiple_choice: "Multiple Choice",
    58→	checkbox: "Checkboxes",
    59→	dropdown: "Dropdown",
    60→	rating: "Rating",
    61→	nps: "NPS",
    62→	linear_scale: "Linear Scale",
    63→	date: "Date",
    64→	email: "Email",
    65→	phone: "Phone",
    66→	file_upload: "File Upload",
    67→};
    68→
    69→// Builder context for sharing state across components
    70→interface SurveyBuilderContextValue {
    71→	survey: Survey;
    72→	questions: Question[];
    73→	selectedQuestionId: string | null;
    74→	setSelectedQuestionId: (id: string | null) => void;
    75→	activeTab: "build" | "preview";
    76→	setActiveTab: (tab: "build" | "preview") => void;
    77→	onQuestionsChange: (questions: Question[]) => void;
    78→	paletteOpen: boolean;
    79→	setPaletteOpen: (open: boolean) => void;
    80→	propertiesOpen: boolean;
    81→	setPropertiesOpen: (open: boolean) => void;
    82→}
    83→
    84→const SurveyBuilderContext = createContext<SurveyBuilderContextValue | null>(
    85→	null,
    86→);
    87→
    88→export function useSurveyBuilder() {
    89→	const context = useContext(SurveyBuilderContext);
    90→	if (!context) {
    91→		throw new Error(
    92→			"useSurveyBuilder must be used within a SurveyBuilder component",
    93→		);
    94→	}
    95→	return context;
    96→}
    97→
    98→// Drag item types
    99→interface PaletteDragItem {
   100→	type: "palette";
   101→	questionType: Question["type"];
   102→}
   103→
   104→interface QuestionDragItem {
   105→	type: "question";
   106→	id: string;
   107→}
   108→
   109→type DragItem = PaletteDragItem | QuestionDragItem;
   110→
   111→interface SurveyBuilderProps {
   112→	survey: Survey;
   113→	questions: Question[];
   114→	className?: string;
   115→}
   116→
   117→export function SurveyBuilder({
   118→	survey,
   119→	questions: initialQuestions,
   120→	className,
   121→}: SurveyBuilderProps) {
   122→	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
   123→		null,
   124→	);
   125→	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
   126→	const [questions, setQuestions] = useState(initialQuestions);
   127→	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
   128→	const [paletteOpen, setPaletteOpen] = useState(false);
   129→	const [propertiesOpen, setPropertiesOpen] = useState(false);
   130→
   131→	// Responsive breakpoints
   132→	const isDesktop = useMediaQuery("(min-width: 1024px)");
   133→
   134→	const queryClient = useQueryClient();
   135→
   136→	// Sync state when initialQuestions changes
   137→	useEffect(() => {
   138→		setQuestions(initialQuestions);
   139→	}, [initialQuestions]);
   140→
   141→	// Create question mutation (for palette drops)
   142→	const createMutation = useMutation(
   143→		orpc.question.create.mutationOptions({
   144→			onSuccess: (newQuestion) => {
   145→				setQuestions((prev) => [...prev, newQuestion]);
   146→				setSelectedQuestionId(newQuestion.id);
   147→				queryClient.invalidateQueries({ queryKey: ["question"] });
   148→				toast.success("Question added");
   149→			},
   150→			onError: (error) => {
   151→				toast.error(error.message || "Failed to create question");
   152→			},
   153→		}),
   154→	);
   155→
   156→	// Reorder mutation
   157→	const reorderMutation = useMutation(
   158→		orpc.question.reorder.mutationOptions({
   159→			onSuccess: () => {
   160→				queryClient.invalidateQueries({ queryKey: ["question"] });
   161→			},
   162→			onError: (error) => {
   163→				toast.error(error.message || "Failed to reorder questions");
   164→			},
   165→		}),
   166→	);
   167→
   168→	// DnD sensors
   169→	const sensors = useSensors(
   170→		useSensor(PointerSensor, {
   171→			activationConstraint: {
   172→				distance: 5,
   173→			},
   174→		}),
   175→		useSensor(KeyboardSensor, {
   176→			coordinateGetter: sortableKeyboardCoordinates,
   177→		}),
   178→	);
   179→
   180→	const handleDragStart = (event: DragStartEvent) => {
   181→		const { active } = event;
   182→		const data = active.data.current;
   183→
   184→		if (data?.questionType) {
   185→			// Dragging from palette
   186→			setActiveDragItem({
   187→				type: "palette",
   188→				questionType: data.questionType as Question["type"],
   189→			});
   190→		} else {
   191→			// Dragging existing question
   192→			setActiveDragItem({
   193→				type: "question",
   194→				id: active.id as string,
   195→			});
   196→		}
   197→	};
   198→
   199→	const handleDragOver = (event: DragOverEvent) => {
   200→		const { active, over } = event;
   201→
   202→		if (!over) return;
   203→
   204→		// Handle palette item over canvas (create new question)
   205→		if (
   206→			active.data.current?.questionType &&
   207→			over.id === "canvas" &&
   208→			!createMutation.isPending
   209→		) {
   210→			const questionType = active.data.current.questionType as Question["type"];
   211→			createMutation.mutate({
   212→				surveyId: survey.id,
   213→				type: questionType,
   214→				title: `New ${questionTypeLabels[questionType] || questionType}`,
   215→				order: questions.length,
   216→			});
   217→			setActiveDragItem(null);
   218→		}
   219→	};
   220→
   221→	const handleDragEnd = (event: DragEndEvent) => {
   222→		const { active, over } = event;
   223→		setActiveDragItem(null);
   224→
   225→		if (!over) return;
   226→
   227→		// Handle reordering
   228→		if (active.id !== over.id && over.id !== "canvas") {
   229→			const oldIndex = questions.findIndex((q) => q.id === active.id);
   230→			const newIndex = questions.findIndex((q) => q.id === over.id);
   231→
   232→			if (oldIndex !== -1 && newIndex !== -1) {
   233→				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
   234→					(q, index) => ({
   235→						...q,
   236→						order: index,
   237→					}),
   238→				);
   239→
   240→				setQuestions(newQuestions);
   241→
   242→				reorderMutation.mutate({
   243→					questions: newQuestions.map((q) => ({
   244→						id: q.id,
   245→						order: q.order,
   246→					})),
   247→				});
   248→			}
   249→		}
   250→	};
   251→
   252→	const contextValue: SurveyBuilderContextValue = {
   253→		survey,
   254→		questions,
   255→		selectedQuestionId,
   256→		setSelectedQuestionId,
   257→		activeTab,
   258→		setActiveTab,
   259→		onQuestionsChange: setQuestions,
   260→		paletteOpen,
   261→		setPaletteOpen,
   262→		propertiesOpen,
   263→		setPropertiesOpen,
   264→	};
   265→
   266→	const safeQuestions = questions || [];
   267→
   268→	// Render drag overlay
   269→	const renderDragOverlay = () => {
   270→		if (!activeDragItem) return null;
   271→
   272→		if (activeDragItem.type === "palette") {
   273→			const Icon =
   274→				questionTypeIcons[activeDragItem.questionType] || ClipboardList;
   275→			return (
   276→				<Card className="shadow-lg">
   277→					<CardContent className="flex items-center gap-3 p-4">
   278→						<GripVertical className="h-4 w-4 text-neutral-400" />
   279→						<Icon className="h-5 w-5 text-violet-500" />
   280→						<span className="font-medium">
   281→							{questionTypeLabels[activeDragItem.questionType] ||
   282→								activeDragItem.questionType}
   283→						</span>
   284→					</CardContent>
   285→				</Card>
   286→			);
   287→		}
   288→
   289→		// Dragging existing question
   290→		const activeQuestion = safeQuestions.find(
   291→			(q) => q.id === activeDragItem.id,
   292→		);
   293→		if (activeQuestion) {
   294→			const Icon = questionTypeIcons[activeQuestion.type] || ClipboardList;
   295→			return (
   296→				<Card className="shadow-lg">
   297→					<CardContent className="flex items-center gap-3 p-4">
   298→						<GripVertical className="h-4 w-4 text-neutral-400" />
   299→						<Icon className="h-5 w-5 text-violet-500" />
   300→						<span className="font-medium">{activeQuestion.title}</span>
   301→					</CardContent>
   302→				</Card>
   303→			);
   304→		}
   305→
   306→		return null;
   307→	};
   308→
   309→	return (
   310→		<SurveyBuilderContext.Provider value={contextValue}>
   311→			<DndContext
   312→				sensors={sensors}
   313→				collisionDetection={closestCenter}
   314→				onDragStart={handleDragStart}
   315→				onDragOver={handleDragOver}
   316→				onDragEnd={handleDragEnd}
   317→			>
   318→				<div className={cn("flex h-full flex-col", className)}>
   319→					<BuilderHeader
   320→						leftActions={
   321→							!isDesktop &&
   322→							activeTab === "build" && (
   323→								<div className="flex items-center gap-1">
   324→									<Button
   325→										variant="ghost"
   326→										size="icon"
   327→										onClick={() => setPaletteOpen(!paletteOpen)}
   328→									>
   329→										<PanelLeftClose className="h-4 w-4" />
   330→									</Button>
   331→								</div>
   332→							)
   333→						}
   334→						rightActions={
   335→							!isDesktop &&
   336→							activeTab === "build" && (
   337→								<div className="flex items-center gap-1">
   338→									<Button
   339→										variant="ghost"
   340→										size="icon"
   341→										onClick={() => setPropertiesOpen(!propertiesOpen)}
   342→									>
   343→										<PanelRightClose className="h-4 w-4" />
   344→									</Button>
   345→								</div>
   346→							)
   347→						}
   348→					/>
   349→					<div className="flex flex-1 overflow-hidden">
   350→						{/* Left Palette - Responsive */}
   351→						{activeTab === "build" && (
   352→							<>
   353→								{/* Desktop: Fixed sidebar */}
   354→								{isDesktop && <QuestionPalette />}
   355→
   356→								{/* Tablet/Mobile: Sheet overlay */}
   357→								{!isDesktop && (
   358→									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
   359→										<SheetContent side="left" className="w-72 p-0">
   360→											<QuestionPalette />
   361→										</SheetContent>
   362→									</Sheet>
   363→								)}
   364→							</>
   365→						)}
   366→
   367→						{/* Canvas */}
   368→						<BuilderCanvas
   369→							questions={questions}
   370→							onQuestionsChange={setQuestions}
   371→						/>
   372→
   373→						{/* Right Properties Panel - Responsive */}
   374→						{activeTab === "build" && (
   375→							<>
   376→								{/* Desktop: Fixed sidebar */}
   377→								{isDesktop && <PropertiesPanel />}
   378→
   379→								{/* Tablet/Mobile: Sheet overlay */}
   380→								{!isDesktop && (
   381→									<Sheet open={propertiesOpen} onOpenChange={setPropertiesOpen}>
   382→										<SheetContent side="right" className="w-80 p-0">
   383→											<PropertiesPanel />
   384→										</SheetContent>
   385→									</Sheet>
   386→								)}
   387→							</>
   388→						)}
   389→					</div>
   390→				</div>
   391→
   392→				<DragOverlay>{renderDragOverlay()}</DragOverlay>
   393→			</DndContext>
   394→		</SurveyBuilderContext.Provider>
   395→	);
   396→}
   397→
   398→export { BuilderCanvas } from "./builder-canvas";
   399→// Re-export sub-components for compound pattern
   400→export { BuilderHeader } from "./builder-header";
   401→export { PropertiesPanel } from "./properties-panel";
   402→export { QuestionPalette } from "./question-palette";
   403→

