"use client";

import { useDraggable } from "@dnd-kit/core";
import type { Question } from "@orksys-survey/db";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import { motion } from "framer-motion";
import {
	Calendar,
	CheckSquare,
	ChevronsUpDown,
	ClipboardList,
	FileText,
	Hash,
	ListChecks,
	Mail,
	MoreHorizontal,
	Phone,
	Star,
	Text,
	TrendingUp,
} from "lucide-react";
import { toast } from "sonner";

import { cn } from "@/lib/utils";
import { orpc } from "@/utils/orpc";

import { useSurveyBuilder } from "./index";

interface QuestionTypeConfig {
	type: Question["type"];
	label: string;
	icon: React.ElementType;
	description: string;
}

const questionTypes: QuestionTypeConfig[] = [
	{
		type: "text",
		label: "Short Text",
		icon: Text,
		description: "Single line text input",
	},
	{
		type: "textarea",
		label: "Long Text",
		icon: FileText,
		description: "Multi-line text area",
	},
	{
		type: "multiple_choice",
		label: "Multiple Choice",
		icon: CheckSquare,
		description: "Single selection from options",
	},
	{
		type: "checkbox",
		label: "Checkboxes",
		icon: ListChecks,
		description: "Multiple selections allowed",
	},
	{
		type: "dropdown",
		label: "Dropdown",
		icon: ChevronsUpDown,
		description: "Dropdown selection list",
	},
	{
		type: "rating",
		label: "Rating",
		icon: Star,
		description: "Star or number rating",
	},
	{
		type: "nps",
		label: "NPS",
		icon: TrendingUp,
		description: "Net Promoter Score 0-10",
	},
	{
		type: "linear_scale",
		label: "Linear Scale",
		icon: Hash,
		description: "Custom range scale",
	},
	{
		type: "date",
		label: "Date",
		icon: Calendar,
		description: "Date picker",
	},
	{
		type: "email",
		label: "Email",
		icon: Mail,
		description: "Email address input",
	},
	{
		type: "phone",
		label: "Phone",
		icon: Phone,
		description: "Phone number input",
	},
	{
		type: "file_upload",
		label: "File Upload",
		icon: ClipboardList,
		description: "File upload field",
	},
];

export function QuestionPalette() {
	const {
		survey,
		questions,
		selectedQuestionId,
		setSelectedQuestionId,
		onQuestionsChange,
	} = useSurveyBuilder();
	const queryClient = useQueryClient();

	const createMutation = useMutation(
		orpc.question.create.mutationOptions({
			onSuccess: (newQuestion) => {
				onQuestionsChange([...(questions || []), newQuestion]);
				setSelectedQuestionId(newQuestion.id);
				queryClient.invalidateQueries({ queryKey: ["question"] });
				toast.success("Question added");
			},
			onError: (error) => {
				toast.error(error.message || "Failed to create question");
			},
		}),
	);

	const handleAddQuestion = (type: Question["type"]) => {
		createMutation.mutate({
			surveyId: survey.id,
			type,
			title: `New ${questionTypes.find((q) => q.type === type)?.label || type}`,
			order: (questions || []).length,
		});
	};

	return (
		<div className="flex h-full w-64 flex-col overflow-y-auto border-neutral-100 border-r bg-white">
			<div className="p-4">
				<h3 className="mb-4 font-bold font-sans text-[10px] text-neutral-900 uppercase tracking-widest">
					Question Types
				</h3>
				<div className="space-y-1">
					{questionTypes.slice(0, 4).map((qType, index) => (
						<QuestionTypeButton
							key={qType.type}
							config={qType}
							onClick={() => handleAddQuestion(qType.type)}
							disabled={createMutation.isPending}
							index={index}
						/>
					))}
				</div>

				<h3 className="mt-6 mb-4 font-bold font-sans text-[10px] text-neutral-900 uppercase tracking-widest">
					More Types
				</h3>
				<div className="grid grid-cols-2 gap-1">
					{questionTypes.slice(4).map((qType, index) => (
						<QuestionTypeIconButton
							key={qType.type}
							config={qType}
							onClick={() => handleAddQuestion(qType.type)}
							disabled={createMutation.isPending}
							index={index}
						/>
					))}
				</div>

				<h3 className="mt-6 mb-4 font-bold font-sans text-[10px] text-neutral-900 uppercase tracking-widest">
					Structure
				</h3>
				<div className="space-y-1">
					{(questions || []).length === 0 ? (
						<p className="py-4 text-center text-neutral-400 text-xs">
							No questions yet
						</p>
					) : (
						(questions || []).map((question, index) => (
							<StructureItem
								key={question.id}
								number={index + 1}
								label={question.title}
								isActive={selectedQuestionId === question.id}
								onClick={() => setSelectedQuestionId(question.id)}
								index={index}
							/>
						))
					)}
				</div>
			</div>
		</div>
	);
}

interface QuestionTypeButtonProps {
	config: QuestionTypeConfig;
	onClick: () => void;
	disabled?: boolean;
	index: number;
}

function QuestionTypeButton({
	config,
	onClick,
	disabled,
	index,
}: QuestionTypeButtonProps) {
	const Icon = config.icon;

	const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
		id: `palette-${config.type}`,
		data: {
			questionType: config.type,
		},
	});

	return (
		<motion.button
			ref={setNodeRef}
			type="button"
			onClick={onClick}
			disabled={disabled}
			{...attributes}
			{...listeners}
			initial={{ opacity: 0, y: 10 }}
			animate={{ opacity: isDragging ? 0.5 : 1, y: 0 }}
			transition={{ duration: 0.2, delay: index * 0.03 }}
			whileHover={{ scale: 1.02 }}
			whileTap={{ scale: 0.98 }}
			className="group flex w-full cursor-grab items-center gap-3 rounded-xl border border-transparent bg-white p-3 text-left transition-colors hover:border-neutral-200 hover:bg-neutral-50 disabled:cursor-not-allowed disabled:opacity-50"
		>
			<Icon className="h-5 w-5 shrink-0 text-neutral-400 transition-colors group-hover:text-violet-500" />
			<div className="min-w-0 flex-1">
				<span className="block font-medium text-neutral-700 text-sm">
					{config.label}
				</span>
				<span className="block truncate text-neutral-400 text-xs">
					{config.description}
				</span>
			</div>
		</motion.button>
	);
}

interface QuestionTypeIconButtonProps {
	config: QuestionTypeConfig;
	onClick: () => void;
	disabled?: boolean;
	index: number;
}

function QuestionTypeIconButton({
	config,
	onClick,
	disabled,
	index,
}: QuestionTypeIconButtonProps) {
	const Icon = config.icon;

	const { attributes, listeners, setNodeRef, isDragging } = useDraggable({
		id: `palette-${config.type}`,
		data: {
			questionType: config.type,
		},
	});

	return (
		<motion.button
			ref={setNodeRef}
			type="button"
			onClick={onClick}
			disabled={disabled}
			{...attributes}
			{...listeners}
			initial={{ opacity: 0, scale: 0.8 }}
			animate={{ opacity: isDragging ? 0.5 : 1, scale: 1 }}
			transition={{ duration: 0.2, delay: index * 0.02 }}
			whileHover={{ scale: 1.05 }}
			whileTap={{ scale: 0.95 }}
			className="group flex flex-col items-center gap-1 rounded-lg border border-transparent bg-white p-2 text-center transition-colors hover:border-neutral-200 hover:bg-neutral-50 disabled:cursor-not-allowed disabled:opacity-50"
			title={config.label}
		>
			<Icon className="h-4 w-4 text-neutral-400 transition-colors group-hover:text-violet-500" />
			<span className="truncate text-[10px] text-neutral-600">
				{config.label}
			</span>
		</motion.button>
	);
}

interface StructureItemProps {
	number: number;
	label: string;
	isActive?: boolean;
	onClick: () => void;
	index: number;
}

function StructureItem({
	number,
	label,
	isActive = false,
	onClick,
	index,
}: StructureItemProps) {
	return (
		<motion.button
			type="button"
			onClick={onClick}
			initial={{ opacity: 0, x: -10 }}
			animate={{ opacity: 1, x: 0 }}
			transition={{ duration: 0.2, delay: index * 0.03 }}
			className={cn(
				"flex w-full items-center justify-between rounded-lg p-2 font-medium text-sm transition-colors",
				isActive
					? "border border-violet-500/20 bg-violet-50 text-neutral-900"
					: "text-neutral-600 hover:bg-neutral-50",
			)}
		>
			<div className="flex items-center gap-2">
				<motion.div
					layoutId={`structure-number-${number}`}
					className={cn(
						"flex h-5 w-5 items-center justify-center rounded text-[10px]",
						isActive
							? "bg-violet-500 text-white"
							: "bg-neutral-200 text-neutral-600",
					)}
				>
					{number}
				</motion.div>
				<span className="truncate">{label}</span>
			</div>
			{isActive && (
				<MoreHorizontal className="h-4 w-4 shrink-0 text-neutral-400" />
			)}
		</motion.button>
	);
}

"use client";

import {
	closestCenter,
	DndContext,
	type DragEndEvent,
	type DragOverEvent,
	DragOverlay,
	type DragStartEvent,
	KeyboardSensor,
	PointerSensor,
	useSensor,
	useSensors,
} from "@dnd-kit/core";
import { arrayMove, sortableKeyboardCoordinates } from "@dnd-kit/sortable";
import type { Question, Survey } from "@orksys-survey/db";
import { useMutation, useQueryClient } from "@tanstack/react-query";
import {
	ClipboardList,
	GripVertical,
	PanelLeftClose,
	PanelRightClose,
} from "lucide-react";
import { createContext, useContext, useEffect, useState } from "react";
import { toast } from "sonner";

import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { Sheet, SheetContent } from "@/components/ui/sheet";
import { useMediaQuery } from "@/hooks/use-media-query";
import { cn } from "@/lib/utils";
import { orpc } from "@/utils/orpc";
import { BuilderCanvas } from "./builder-canvas";
import { BuilderHeader } from "./builder-header";
import { PropertiesPanel } from "./properties-panel";
import { QuestionPalette } from "./question-palette";

// Question type configs for drag overlay
const questionTypeIcons: Record<string, React.ElementType> = {
	text: ClipboardList,
	textarea: ClipboardList,
	multiple_choice: ClipboardList,
	checkbox: ClipboardList,
	dropdown: ClipboardList,
	rating: ClipboardList,
	nps: ClipboardList,
	linear_scale: ClipboardList,
	date: ClipboardList,
	email: ClipboardList,
	phone: ClipboardList,
	file_upload: ClipboardList,
};

const questionTypeLabels: Record<string, string> = {
	text: "Short Text",
	textarea: "Long Text",
	multiple_choice: "Multiple Choice",
	checkbox: "Checkboxes",
	dropdown: "Dropdown",
	rating: "Rating",
	nps: "NPS",
	linear_scale: "Linear Scale",
	date: "Date",
	email: "Email",
	phone: "Phone",
	file_upload: "File Upload",
};

// Builder context for sharing state across components
interface SurveyBuilderContextValue {
	survey: Survey;
	questions: Question[];
	selectedQuestionId: string | null;
	setSelectedQuestionId: (id: string | null) => void;
	activeTab: "build" | "preview";
	setActiveTab: (tab: "build" | "preview") => void;
	onQuestionsChange: (questions: Question[]) => void;
	paletteOpen: boolean;
	setPaletteOpen: (open: boolean) => void;
	propertiesOpen: boolean;
	setPropertiesOpen: (open: boolean) => void;
}

const SurveyBuilderContext = createContext<SurveyBuilderContextValue | null>(
	null,
);

export function useSurveyBuilder() {
	const context = useContext(SurveyBuilderContext);
	if (!context) {
		throw new Error(
			"useSurveyBuilder must be used within a SurveyBuilder component",
		);
	}
	return context;
}

// Drag item types
interface PaletteDragItem {
	type: "palette";
	questionType: Question["type"];
}

interface QuestionDragItem {
	type: "question";
	id: string;
}

type DragItem = PaletteDragItem | QuestionDragItem;

interface SurveyBuilderProps {
	survey: Survey;
	questions: Question[];
	className?: string;
}

export function SurveyBuilder({
	survey,
	questions: initialQuestions,
	className,
}: SurveyBuilderProps) {
	const [selectedQuestionId, setSelectedQuestionId] = useState<string | null>(
		null,
	);
	const [activeTab, setActiveTab] = useState<"build" | "preview">("build");
	const [questions, setQuestions] = useState(initialQuestions);
	const [activeDragItem, setActiveDragItem] = useState<DragItem | null>(null);
	const [paletteOpen, setPaletteOpen] = useState(false);
	const [propertiesOpen, setPropertiesOpen] = useState(false);

	// Responsive breakpoints
	const isDesktop = useMediaQuery("(min-width: 1024px)");

	const queryClient = useQueryClient();

	// Sync state when initialQuestions changes
	useEffect(() => {
		setQuestions(initialQuestions);
	}, [initialQuestions]);

	// Create question mutation (for palette drops)
	const createMutation = useMutation(
		orpc.question.create.mutationOptions({
			onSuccess: (newQuestion) => {
				setQuestions((prev) => [...prev, newQuestion]);
				setSelectedQuestionId(newQuestion.id);
				queryClient.invalidateQueries({ queryKey: ["question"] });
				toast.success("Question added");
			},
			onError: (error) => {
				toast.error(error.message || "Failed to create question");
			},
		}),
	);

	// Reorder mutation
	const reorderMutation = useMutation(
		orpc.question.reorder.mutationOptions({
			onSuccess: () => {
				queryClient.invalidateQueries({ queryKey: ["question"] });
			},
			onError: (error) => {
				toast.error(error.message || "Failed to reorder questions");
			},
		}),
	);

	// DnD sensors
	const sensors = useSensors(
		useSensor(PointerSensor, {
			activationConstraint: {
				distance: 5,
			},
		}),
		useSensor(KeyboardSensor, {
			coordinateGetter: sortableKeyboardCoordinates,
		}),
	);

	const handleDragStart = (event: DragStartEvent) => {
		const { active } = event;
		const data = active.data.current;

		if (data?.questionType) {
			// Dragging from palette
			setActiveDragItem({
				type: "palette",
				questionType: data.questionType as Question["type"],
			});
		} else {
			// Dragging existing question
			setActiveDragItem({
				type: "question",
				id: active.id as string,
			});
		}
	};

	const handleDragOver = (event: DragOverEvent) => {
		const { active, over } = event;

		if (!over) return;

		// Handle palette item over canvas (create new question)
		if (
			active.data.current?.questionType &&
			over.id === "canvas" &&
			!createMutation.isPending
		) {
			const questionType = active.data.current.questionType as Question["type"];
			createMutation.mutate({
				surveyId: survey.id,
				type: questionType,
				title: `New ${questionTypeLabels[questionType] || questionType}`,
				order: questions.length,
			});
			setActiveDragItem(null);
		}
	};

	const handleDragEnd = (event: DragEndEvent) => {
		const { active, over } = event;
		setActiveDragItem(null);

		if (!over) return;

		// Handle reordering
		if (active.id !== over.id && over.id !== "canvas") {
			const oldIndex = questions.findIndex((q) => q.id === active.id);
			const newIndex = questions.findIndex((q) => q.id === over.id);

			if (oldIndex !== -1 && newIndex !== -1) {
				const newQuestions = arrayMove(questions, oldIndex, newIndex).map(
					(q, index) => ({
						...q,
						order: index,
					}),
				);

				setQuestions(newQuestions);

				reorderMutation.mutate({
					questions: newQuestions.map((q) => ({
						id: q.id,
						order: q.order,
					})),
				});
			}
		}
	};

	const contextValue: SurveyBuilderContextValue = {
		survey,
		questions,
		selectedQuestionId,
		setSelectedQuestionId,
		activeTab,
		setActiveTab,
		onQuestionsChange: setQuestions,
		paletteOpen,
		setPaletteOpen,
		propertiesOpen,
		setPropertiesOpen,
	};

	const safeQuestions = questions || [];

	// Render drag overlay
	const renderDragOverlay = () => {
		if (!activeDragItem) return null;

		if (activeDragItem.type === "palette") {
			const Icon =
				questionTypeIcons[activeDragItem.questionType] || ClipboardList;
			return (
				<Card className="shadow-lg">
					<CardContent className="flex items-center gap-3 p-4">
						<GripVertical className="h-4 w-4 text-neutral-400" />
						<Icon className="h-5 w-5 text-violet-500" />
						<span className="font-medium">
							{questionTypeLabels[activeDragItem.questionType] ||
								activeDragItem.questionType}
						</span>
					</CardContent>
				</Card>
			);
		}

		// Dragging existing question
		const activeQuestion = safeQuestions.find(
			(q) => q.id === activeDragItem.id,
		);
		if (activeQuestion) {
			const Icon = questionTypeIcons[activeQuestion.type] || ClipboardList;
			return (
				<Card className="shadow-lg">
					<CardContent className="flex items-center gap-3 p-4">
						<GripVertical className="h-4 w-4 text-neutral-400" />
						<Icon className="h-5 w-5 text-violet-500" />
						<span className="font-medium">{activeQuestion.title}</span>
					</CardContent>
				</Card>
			);
		}

		return null;
	};

	return (
		<SurveyBuilderContext.Provider value={contextValue}>
			<DndContext
				sensors={sensors}
				collisionDetection={closestCenter}
				onDragStart={handleDragStart}
				onDragOver={handleDragOver}
				onDragEnd={handleDragEnd}
			>
				<div className={cn("flex h-full flex-col", className)}>
					<BuilderHeader
						leftActions={
							!isDesktop &&
							activeTab === "build" && (
								<div className="flex items-center gap-1">
									<Button
										variant="ghost"
										size="icon"
										onClick={() => setPaletteOpen(!paletteOpen)}
									>
										<PanelLeftClose className="h-4 w-4" />
									</Button>
								</div>
							)
						}
						rightActions={
							!isDesktop &&
							activeTab === "build" && (
								<div className="flex items-center gap-1">
									<Button
										variant="ghost"
										size="icon"
										onClick={() => setPropertiesOpen(!propertiesOpen)}
									>
										<PanelRightClose className="h-4 w-4" />
									</Button>
								</div>
							)
						}
					/>
					<div className="flex flex-1 overflow-hidden">
						{/* Left Palette - Responsive */}
						{activeTab === "build" && (
							<>
								{/* Desktop: Fixed sidebar */}
								{isDesktop && <QuestionPalette />}

								{/* Tablet/Mobile: Sheet overlay */}
								{!isDesktop && (
									<Sheet open={paletteOpen} onOpenChange={setPaletteOpen}>
										<SheetContent side="left" className="w-72 p-0">
											<QuestionPalette />
										</SheetContent>
									</Sheet>
								)}
							</>
						)}

						{/* Canvas */}
						<BuilderCanvas
							questions={questions}
							onQuestionsChange={setQuestions}
						/>

						{/* Right Properties Panel - Responsive */}
						{activeTab === "build" && (
							<>
								{/* Desktop: Fixed sidebar */}
								{isDesktop && <PropertiesPanel />}

								{/* Tablet/Mobile: Sheet overlay */}
								{!isDesktop && (
									<Sheet open={propertiesOpen} onOpenChange={setPropertiesOpen}>
										<SheetContent side="right" className="w-80 p-0">
											<PropertiesPanel />
										</SheetContent>
									</Sheet>
								)}
							</>
						)}
					</div>
				</div>

				<DragOverlay>{renderDragOverlay()}</DragOverlay>
			</DndContext>
		</SurveyBuilderContext.Provider>
	);
}

